INSERT INTO questions (id, class_session_id, title, difficulty, statement_markdown, constraints, examples, starter_code_java, test_cases, tags, order_index) VALUES
('e0000006-0021-0001-000000000000', 'd0000001-0021-4000-8000-000000000001', 'Time Complexity Growth Estimation', 'EASY', 'Read N, output N^2 operations count.', '["Time Limit: 2.0s"]', '[{"input": "10", "output": "100", "explanation": "10*10=100"}]', 'import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        long n = new Scanner(System.in).nextLong();\n        System.out.println(n * n);\n    }\n}', '[{"input": "10\\n", "expected_output": "100\\n", "hidden": false}]', '["complexity"]', 1),
('e0000006-0022-0001-000000000000', 'd0000001-0022-4000-8000-000000000001', 'Logarithmic Operations Tracker', 'EASY', 'Read N, print floor(log2(N)).', '["Time Limit: 2.0s"]', '[{"input": "16", "output": "4", "explanation": "log2(16)=4"}]', 'import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        long n = new Scanner(System.in).nextLong();\n        System.out.println((int)(Math.log(n) / Math.log(2)));\n    }\n}', '[{"input": "16\\n", "expected_output": "4\\n", "hidden": false}]', '["complexity"]', 1),
('e0000006-0023-0001-000000000000', 'd0000001-0023-4000-8000-000000000001', 'Missing Number in Range', 'EASY', 'Given N numbers in range 0..N with one missing, find missing number.', '["Time Limit: 2.0s"]', '[{"input": "3\\n3 0 1", "output": "2", "explanation": "2 is missing"}]', 'import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt(), expected = n * (n + 1) / 2, sum = 0;\n        for(int i=0; i<n; i++) sum += sc.nextInt();\n        System.out.println(expected - sum);\n    }\n}', '[{"input": "3\\n3 0 1\\n", "expected_output": "2\\n", "hidden": false}]', '["searching"]', 1),
('e0000006-0024-0002-000000000000', 'd0000001-0024-4000-8000-000000000001', 'Find Element Frequency', 'EASY', 'Count frequency of key K in array.', '["Time Limit: 2.0s"]', '[{"input": "5 2\\n1 2 2 3 2", "output": "3", "explanation": "2 appears 3 times"}]', 'import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt(), k = sc.nextInt(), c = 0;\n        for(int i=0; i<n; i++) if (sc.nextInt() == k) c++;\n        System.out.println(c);\n    }\n}', '[{"input": "5 2\\n1 2 2 3 2\\n", "expected_output": "3\\n", "hidden": false}]', '["searching"]', 2),
('e0000006-0025-0001-000000000000', 'd0000001-0025-4000-8000-000000000001', 'Majority Element (>N/2 times)', 'MEDIUM', 'Find element appearing more than N/2 times using Boyer-Moore Voting algorithm.', '["Time Limit: 2.0s"]', '[{"input": "7\\n2 2 1 1 1 2 2", "output": "2", "explanation": "2 appears 4 times (>7/2)"}]', 'import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt(), cand = 0, count = 0;\n        for(int i=0; i<n; i++) {\n            int v = sc.nextInt();\n            if (count == 0) cand = v;\n            count += (v == cand) ? 1 : -1;\n        }\n        System.out.println(cand);\n    }\n}', '[{"input": "7\\n2 2 1 1 1 2 2\\n", "expected_output": "2\\n", "hidden": false}]', '["searching"]', 1);
INSERT INTO questions (id, class_session_id, title, difficulty, statement_markdown, constraints, examples, starter_code_java, test_cases, tags, order_index) VALUES
('e0000006-0026-0002-000000000000', 'd0000001-0026-4000-8000-000000000001', 'First Occurrence Index', 'EASY', 'Binary search for first occurrence index of key K in sorted array with duplicates.', '["Time Limit: 2.0s"]', '[{"input": "6 2\\n1 2 2 2 3 4", "output": "1", "explanation": "First 2 is at index 1"}]', 'import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt(), k = sc.nextInt();\n        int[] a = new int[n];\n        for(int i=0; i<n; i++) a[i] = sc.nextInt();\n        int low = 0, high = n - 1, ans = -1;\n        while(low <= high) {\n            int mid = (low + high) / 2;\n            if (a[mid] == k) { ans = mid; high = mid - 1; }\n            else if (a[mid] < k) low = mid + 1;\n            else high = mid - 1;\n        }\n        System.out.println(ans);\n    }\n}', '[{"input": "6 2\\n1 2 2 2 3 4\\n", "expected_output": "1\\n", "hidden": false}]', '["binary-search"]', 2),
('e0000006-0027-0001-000000000000', 'd0000001-0027-4000-8000-000000000001', 'Square Root Floor (Integer)', 'EASY', 'Compute floor(sqrt(N)) using Binary Search.', '["Time Limit: 2.0s"]', '[{"input": "8", "output": "2", "explanation": "sqrt(8) floor is 2"}]', 'import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        long n = sc.nextLong(), l = 0, r = n, ans = 0;\n        while(l <= r) {\n            long m = (l + r) / 2;\n            if (m * m <= n) { ans = m; l = m + 1; }\n            else r = m - 1;\n        }\n        System.out.println(ans);\n    }\n}', '[{"input": "8\\n", "expected_output": "2\\n", "hidden": false}]', '["binary-search"]', 1),
('e0000006-0028-0001-000000000000', 'd0000001-0028-4000-8000-000000000001', 'Search Insert Position', 'EASY', 'Find index where target K should be inserted to keep array sorted.', '["Time Limit: 2.0s"]', '[{"input": "4 5\\n1 3 5 6", "output": "2", "explanation": "5 is at index 2"}]', 'import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt(), k = sc.nextInt();\n        int[] a = new int[n];\n        for(int i=0; i<n; i++) a[i] = sc.nextInt();\n        int l = 0, r = n - 1, ans = n;\n        while(l <= r) {\n            int m = (l + r) / 2;\n            if (a[m] >= k) { ans = m; r = m - 1; }\n            else l = m + 1;\n        }\n        System.out.println(ans);\n    }\n}', '[{"input": "4 5\\n1 3 5 6\\n", "expected_output": "2\\n", "hidden": false}]', '["binary-search"]', 1),
('e0000006-0029-0001-000000000000', 'd0000001-0029-4000-8000-000000000001', 'Search in Rotated Sorted Array', 'MEDIUM', 'Find target K in a rotated sorted array in O(log N). Print index or -1.', '["Time Limit: 2.0s"]', '[{"input": "7 0\\n4 5 6 7 0 1 2", "output": "4", "explanation": "0 is at index 4"}]', 'import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt(), target = sc.nextInt();\n        int[] nums = new int[n];\n        for(int i=0; i<n; i++) nums[i] = sc.nextInt();\n        int l = 0, r = n - 1, ans = -1;\n        while(l <= r) {\n            int m = (l + r) / 2;\n            if (nums[m] == target) { ans = m; break; }\n            if (nums[l] <= nums[m]) {\n                if (target >= nums[l] && target < nums[m]) r = m - 1;\n                else l = m + 1;\n            } else {\n                if (target > nums[m] && target <= nums[r]) l = m + 1;\n                else r = m - 1;\n            }\n        }\n        System.out.println(ans);\n    }\n}', '[{"input": "7 0\\n4 5 6 7 0 1 2\\n", "expected_output": "4\\n", "hidden": false}]', '["binary-search"]', 1),
('e0000006-0030-0001-000000000000', 'd0000001-0030-4000-8000-000000000001', 'Find Peak Element Index', 'MEDIUM', 'Find index of an element strictly greater than its neighbors.', '["Time Limit: 2.0s"]', '[{"input": "4\\n1 2 3 1", "output": "2", "explanation": "Peak 3 at index 2"}]', 'import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int[] a = new int[n];\n        for(int i=0; i<n; i++) a[i] = sc.nextInt();\n        for(int i=0; i<n; i++) {\n            boolean left = (i == 0 || a[i] > a[i-1]);\n            boolean right = (i == n-1 || a[i] > a[i+1]);\n            if (left && right) { System.out.println(i); break; }\n        }\n    }\n}', '[{"input": "4\\n1 2 3 1\\n", "expected_output": "2\\n", "hidden": false}]', '["binary-search"]', 1);
INSERT INTO questions (id, class_session_id, title, difficulty, statement_markdown, constraints, examples, starter_code_java, test_cases, tags, order_index) VALUES
('e0000006-0031-0001-000000000000', 'd0000001-0031-4000-8000-000000000001', 'Bubble Sort Pass Tracker', 'EASY', 'Sort array using Bubble Sort and print total swap count.', '["Time Limit: 2.0s"]', '[{"input": "4\\n4 3 2 1", "output": "6", "explanation": "6 swaps needed"}]', 'import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int[] a = new int[n]; for(int i=0; i<n; i++) a[i] = sc.nextInt();\n        int swaps = 0;\n        for(int i=0; i<n; i++) for(int j=0; j<n-i-1; j++) if(a[j] > a[j+1]) { int t = a[j]; a[j] = a[j+1]; a[j+1] = t; swaps++; }\n        System.out.println(swaps);\n    }\n}', '[{"input": "4\\n4 3 2 1\\n", "expected_output": "6\\n", "hidden": false}]', '["sorting"]', 1),
('e0000006-0032-0001-000000000000', 'd0000001-0032-4000-8000-000000000001', 'Selection Sort Step Tracker', 'EASY', 'Print array sorted using Selection Sort.', '["Time Limit: 2.0s"]', '[{"input": "5\\n64 25 12 22 11", "output": "11 12 22 25 64 ", "explanation": "Sorted order"}]', 'import java.util.Scanner;\nimport java.util.Arrays;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int[] a = new int[n]; for(int i=0; i<n; i++) a[i] = sc.nextInt();\n        Arrays.sort(a);\n        for(int x : a) System.out.print(x + " ");\n        System.out.println();\n    }\n}', '[{"input": "5\\n64 25 12 22 11\\n", "expected_output": "11 12 22 25 64 \\n", "hidden": false}]', '["sorting"]', 1),
('e0000006-0033-0001-000000000000', 'd0000001-0033-4000-8000-000000000001', 'Matrix Row Sums', 'EASY', 'Given R x C matrix, print sum of each row on separate lines.', '["Time Limit: 2.0s"]', '[{"input": "2 3\\n1 2 3\\n4 5 6", "output": "6\\n15", "explanation": "Row sums"}]', 'import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int r = sc.nextInt(), c = sc.nextInt();\n        for(int i=0; i<r; i++) {\n            int sum = 0;\n            for(int j=0; j<c; j++) sum += sc.nextInt();\n            System.out.println(sum);\n        }\n    }\n}', '[{"input": "2 3\\n1 2 3\\n4 5 6\\n", "expected_output": "6\\n15\\n", "hidden": false}]', '["2d-arrays"]', 1),
('e0000006-0034-0001-000000000000', 'd0000001-0034-4000-8000-000000000001', 'Transpose of Matrix', 'MEDIUM', 'Print transpose of R x C matrix.', '["Time Limit: 2.0s"]', '[{"input": "2 3\\n1 2 3\\n4 5 6", "output": "1 4 \\n2 5 \\n3 6 ", "explanation": "Transposed"}]', 'import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int r = sc.nextInt(), c = sc.nextInt();\n        int[][] m = new int[r][c];\n        for(int i=0; i<r; i++) for(int j=0; j<c; j++) m[i][j] = sc.nextInt();\n        for(int j=0; j<c; j++) {\n            for(int i=0; i<r; i++) System.out.print(m[i][j] + " ");\n            System.out.println();\n        }\n    }\n}', '[{"input": "2 3\\n1 2 3\\n4 5 6\\n", "expected_output": "1 4 \\n2 5 \\n3 6 \\n", "hidden": false}]', '["2d-arrays"]', 1),
('e0000006-0035-0001-000000000000', 'd0000001-0035-4000-8000-000000000001', 'Spiral Traversal of Matrix', 'MEDIUM', 'Print elements of R x C matrix in spiral order.', '["Time Limit: 2.0s"]', '[{"input": "3 3\\n1 2 3\\n4 5 6\\n7 8 9", "output": "1 2 3 6 9 8 7 4 5 ", "explanation": "Spiral order"}]', 'import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int r = sc.nextInt(), c = sc.nextInt();\n        int[][] m = new int[r][c];\n        for(int i=0; i<r; i++) for(int j=0; j<c; j++) m[i][j] = sc.nextInt();\n        int top = 0, bottom = r - 1, left = 0, right = c - 1;\n        while(top <= bottom && left <= right) {\n            for(int j=left; j<=right; j++) System.out.print(m[top][j] + " ");\n            top++;\n            for(int i=top; i<=bottom; i++) System.out.print(m[i][right] + " ");\n            right--;\n            if(top <= bottom) { for(int j=right; j>=left; j--) System.out.print(m[bottom][j] + " "); bottom--; }\n            if(left <= right) { for(int i=bottom; i>=top; i--) System.out.print(m[i][left] + " "); left++; }\n        }\n        System.out.println();\n    }\n}', '[{"input": "3 3\\n1 2 3\\n4 5 6\\n7 8 9\\n", "expected_output": "1 2 3 6 9 8 7 4 5 \\n", "hidden": false}]', '["2d-arrays"]', 1);
INSERT INTO questions (id, class_session_id, title, difficulty, statement_markdown, constraints, examples, starter_code_java, test_cases, tags, order_index) VALUES
('e0000006-0036-0001-000000000000', 'd0000001-0036-4000-8000-000000000001', 'Check Valid Palindrome String', 'EASY', 'Read string S (ignoring non-alphanumeric case-insensitively). Output YES or NO.', '["Time Limit: 2.0s"]', '[{"input": "A man, a plan, a canal: Panama", "output": "YES", "explanation": "Palindrome"}]', 'import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        String s = sc.nextLine().replaceAll("[^a-zA-Z0-9]", "").toLowerCase();\n        String rev = new StringBuilder(s).reverse().toString();\n        System.out.println(s.equals(rev) ? "YES" : "NO");\n    }\n}', '[{"input": "A man, a plan, a canal: Panama\\n", "expected_output": "YES\\n", "hidden": false}]', '["strings"]', 1),
('e0000006-0037-0001-000000000000', 'd0000001-0037-4000-8000-000000000001', 'Count Vowels and Consonants', 'EASY', 'Count vowels and consonants in string S.', '["Time Limit: 2.0s"]', '[{"input": "hello", "output": "Vowels: 2, Consonants: 3", "explanation": "V:2 C:3"}]', 'import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        String s = sc.next().toLowerCase();\n        int v = 0, c = 0;\n        for(char ch : s.toCharArray()) {\n            if("aeiou".indexOf(ch) != -1) v++;\n            else if(ch >= \'a\' && ch <= \'z\') c++;\n        }\n        System.out.println("Vowels: " + v + ", Consonants: " + c);\n    }\n}', '[{"input": "hello\\n", "expected_output": "Vowels: 2, Consonants: 3\\n", "hidden": false}]', '["strings"]', 1),
('e0000006-0038-0001-000000000000', 'd0000001-0038-4000-8000-000000000001', 'Two Sum II (Sorted Array)', 'MEDIUM', 'Find 1-based indices of two numbers in sorted array that add up to target K.', '["Time Limit: 2.0s"]', '[{"input": "4 9\\n2 7 11 15", "output": "1 2", "explanation": "2+7=9"}]', 'import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt(), target = sc.nextInt();\n        int[] a = new int[n]; for(int i=0; i<n; i++) a[i] = sc.nextInt();\n        int l = 0, r = n - 1;\n        while(l < r) {\n            int sum = a[l] + a[r];\n            if (sum == target) { System.out.println((l+1) + " " + (r+1)); break; }\n            else if (sum < target) l++;\n            else r--;\n        }\n    }\n}', '[{"input": "4 9\\n2 7 11 15\\n", "expected_output": "1 2\\n", "hidden": false}]', '["two-pointers"]', 1),
('e0000006-0039-0001-000000000000', 'd0000001-0039-4000-8000-000000000001', 'Max Consecutive Ones', 'EASY', 'Find max consecutive 1s in a binary array.', '["Time Limit: 2.0s"]', '[{"input": "6\\n1 1 0 1 1 1", "output": "3", "explanation": "3 ones"}]', 'import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt(), max = 0, curr = 0;\n        for(int i=0; i<n; i++) {\n            if (sc.nextInt() == 1) { curr++; max = Math.max(max, curr); }\n            else curr = 0;\n        }\n        System.out.println(max);\n    }\n}', '[{"input": "6\\n1 1 0 1 1 1\\n", "expected_output": "3\\n", "hidden": false}]', '["arrays"]', 1),
('e0000006-0040-0001-000000000000', 'd0000001-0040-4000-8000-000000000001', 'Container With Most Water', 'MEDIUM', 'Given N heights, find max area of water a container can store.', '["Time Limit: 2.0s"]', '[{"input": "5\\n1 8 6 2 5", "output": "24", "explanation": "Max area 24"}]', 'import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int[] h = new int[n]; for(int i=0; i<n; i++) h[i] = sc.nextInt();\n        int l = 0, r = n - 1, maxArea = 0;\n        while(l < r) {\n            int area = Math.min(h[l], h[r]) * (r - l);\n            maxArea = Math.max(maxArea, area);\n            if (h[l] < h[r]) l++; else r--;\n        }\n        System.out.println(maxArea);\n    }\n}', '[{"input": "5\\n1 8 6 2 5\\n", "expected_output": "24\\n", "hidden": false}]', '["two-pointers"]', 1);
